/* C API of the Rust port of `src/facade.c`, generated by everything-rust. */
#ifndef FACADE_RS_H
#define FACADE_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

long parse_long(const char *text, int base);
int parse_int(const char *text);
double parse_double(const char *text);
size_t span(const char *text, const char *accept);
int compare(const char *a, const char *b);
int is_alpha(int c);
int is_space(int c);
int is_punct(int c);
int to_upper(int c);

/* The same functions under `everything_rust_` names, for shadow runs. */
long everything_rust_parse_long(const char *text, int base);
int everything_rust_parse_int(const char *text);
double everything_rust_parse_double(const char *text);
size_t everything_rust_span(const char *text, const char *accept);
int everything_rust_compare(const char *a, const char *b);
int everything_rust_is_alpha(int c);
int everything_rust_is_space(int c);
int everything_rust_is_punct(int c);
int everything_rust_to_upper(int c);

#endif /* FACADE_RS_H */
